    }

    /// Create a batch from unbatched events
    pub fn create_batch(&mut self) -> Option<&EventBatch> {
        let last_batched = self.batches.last().map(|b| b.last_event_id).unwrap_or(0);
        let unbatched: Vec<_> = self
