        }
        "local" => {
            info!("Creating local chatbot configuration (loopback only)");
            ClientConfig::for_local_chatbot(&client_id)
        }
        _ => {
            warn!(
                "Unknown client type '{}', using default external client",
                cli.client_type
            );
            ClientConfig::for_external_client(&client_id)
        }
    };

